CREATE TABLE T_ReservedSeatSection
(
    reserved_seat_id    BIGSERIAL  NOT NULL PRIMARY KEY,
    ride_date           DATE       NOT NULL,
    schedule_cd         VARCHAR(6) NOT NULL REFERENCES M_Schedule (schedule_cd) ON DELETE CASCADE,
    train_car_cd        VARCHAR(7) NOT NULL REFERENCES M_TrainCar (train_car_cd) ON DELETE CASCADE,
    seat_cd             VARCHAR(9) NOT NULL REFERENCES M_Seat (seat_cd) ON DELETE CASCADE,
    reserved_section_cd VARCHAR(5) NOT NULL REFERENCES M_SectionKm (section_cd) ON DELETE CASCADE,
    UNIQUE (ride_date, schedule_cd, train_car_cd, seat_cd, reserved_section_cd)
);

